CREATE OR REPLACE FUNCTION mission_factory_owner.c474_import_fork_v1(p_original uuid, p_original_version bigint, p_target uuid, p_target_version bigint, p_request uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t mission_factory_owner.c464_transfer_sources;
BEGIN
 SELECT * INTO t FROM mission_factory_owner.c464_transfer_sources WHERE target_draft_id=p_original AND target_version=p_original_version;
 IF NOT FOUND THEN RETURN;END IF;
 PERFORM mission_factory_owner.c464_fork_transfer_v1(extensions.uuid_generate_v5(p_request,'g2-dual-fork'),t.id,p_target,p_target_version);
END $function$
